fn r_start(p: &mut Parser) -> PResult {
    p.positive_closure(|p| {
        p.closure(|p| {
            p.call(R_SEPARATOR_WITH_SPACE)?;
            Ok(())
        })?;
        p.closure(|p| {
            p.call(R_HSPACE)?;
            Ok(())
        })?;
        p.call(R_VALID_BLOCK)?;
        p.add_last_node_to_name("vblock");
        p.closure(|p| {
            p.call(R_SEPARATOR_WITH_SPACE)?;
            Ok(())
        })?;
        p.define(&[], &["vblock"]);
        Ok(())
    })?;
    p.closure(|p| {
        p.call(R_BLANK)?;
        Ok(())
    })?;
    p.check_eof()?;
    p.define(&[], &["vblock"]);
    Ok(())
}

