fn r_sin_func(p: &mut Parser) -> PResult {
    p.call(R_SIN_U)?;
    p.closure(|p| {
        p.choice(|p| {
            if p.option(|p| {
                p.group(|p| {
                    p.token("^")?;
                    p.call(R_INTEGER)?;
                    p.name_last_node("power");
                    p.define(&["power"], &[]);
                    Ok(())
                })?;
                Ok(())
            }) {
                return Ok(());
            }
            if p.option(|p| {
                p.call(R_SUP_INTEGER)?;
                p.name_last_node("power");
                Ok(())
            }) {
                return Ok(());
            }
            Err(p.error("expecting one of: '^' <sup_integer>"))
        })?;
        Ok(())
    })?;
    p.token("(")?;
    p.closure(|p| {
        p.call(R_HSPACE)?;
        Ok(())
    })?;
    p.call(R_EXPRESSION)?;
    p.name_last_node("param");
    p.closure(|p| {
        p.call(R_HSPACE)?;
        Ok(())
    })?;
    p.token(")")?;
    p.define(&["param", "power"], &[]);
    Ok(())
}

